// BD-410 stage 1: the DxgkDdiQueryInterface answer for OPM, the protected output handles, the refused OPM calls
// (opm_policy.h) and the log rule of the query (query_interface_policy.h). No lab access.
// opm_wdk_guids.h is generated by run_opm_policy.ps1 from every DEFINE_GUID of the WDK's km/dispmprt.h, so the
// GUIDs below are the WDK's and none is typed by hand.
#include <stdio.h>
#include <string.h>
#include "opm_policy.h"
#include "query_interface_policy.h"
#include "opm_wdk_guids.h"

static unsigned checks, bad;
#define CHECK(x) do{++checks;if(!(x)){++bad;printf("FAIL line %d: %s\n",__LINE__,#x);}}while(0)

// sizeof(DXGK_OPM_INTERFACE) and DXGK_OPM_INTERFACE_VERSION_1 in the WDK; the runner's kernel probe asserts both.
#define V1_SIZE 104u
#define V1_VERSION 1u
#define TARGET 0x250001u   // BC250_CHILD_UID, the one VidPN target
#define SENTINEL 0x5A5A5A5A5A5A5A5Aull

static const unsigned char* guid_named(const char* name)
{
    unsigned i;
    for (i = 0; i < OPM_WDK_GUID_COUNT; ++i) if (strcmp(OpmWdkGuids[i].Name, name) == 0) return OpmWdkGuids[i].Bytes;
    return 0;
}

static void query_interface(void)
{
    const unsigned char* opm = guid_named("GUID_DEVINTERFACE_OPM");
    int iface = 0;
    unsigned i, v, b;
    unsigned char near[16];

    CHECK(OPM_WDK_GUID_COUNT >= 10u);
    CHECK(opm != 0);
    CHECK(guid_named("GUID_DEVINTERFACE_OPM_2") != 0);
    CHECK(guid_named("GUID_DEVINTERFACE_OPM_2_JTP") != 0);
    CHECK(guid_named("GUID_DEVINTERFACE_OPM_3") != 0);
    if (!opm) return;

    // The one accepted request, and a larger buffer for it.
    CHECK(OpmQueryInterfaceAnswer(opm, opm, V1_SIZE, V1_VERSION, &iface, V1_SIZE, V1_VERSION) == OPM_STATUS_SUCCESS);
    CHECK(OpmQueryInterfaceAnswer(opm, opm, V1_SIZE + 8u, V1_VERSION, &iface, V1_SIZE, V1_VERSION) == OPM_STATUS_SUCCESS);
    // The size check: a buffer that cannot hold the version 1 structure.
    CHECK(OpmQueryInterfaceAnswer(opm, opm, V1_SIZE - 1u, V1_VERSION, &iface, V1_SIZE, V1_VERSION) == OPM_STATUS_NOT_SUPPORTED);
    CHECK(OpmQueryInterfaceAnswer(opm, opm, 0u, V1_VERSION, &iface, V1_SIZE, V1_VERSION) == OPM_STATUS_NOT_SUPPORTED);
    // The version check: every other version of the OPM GUID.
    for (v = 0; v <= 8u; ++v) {
        if (v == V1_VERSION) continue;
        CHECK(OpmQueryInterfaceAnswer(opm, opm, V1_SIZE, v, &iface, V1_SIZE, V1_VERSION) == OPM_STATUS_NOT_SUPPORTED);
        CHECK(OpmQueryInterfaceAnswer(opm, opm, 0xFFFFu, v, &iface, V1_SIZE, V1_VERSION) == OPM_STATUS_NOT_SUPPORTED);
    }
    // No structure to fill, no GUID.
    CHECK(OpmQueryInterfaceAnswer(opm, opm, V1_SIZE, V1_VERSION, 0, V1_SIZE, V1_VERSION) == OPM_STATUS_NOT_SUPPORTED);
    CHECK(OpmQueryInterfaceAnswer(0, opm, V1_SIZE, V1_VERSION, &iface, V1_SIZE, V1_VERSION) == OPM_STATUS_NOT_SUPPORTED);
    // Every other GUID of the WDK header, in every version and size that would pass for the OPM GUID.
    for (i = 0; i < OPM_WDK_GUID_COUNT; ++i) {
        if (OpmWdkGuids[i].Bytes == opm) continue;
        for (v = 0; v <= 8u; ++v) {
            CHECK(OpmQueryInterfaceAnswer(OpmWdkGuids[i].Bytes, opm, V1_SIZE, v, &iface, V1_SIZE, V1_VERSION) ==
                  OPM_STATUS_NOT_SUPPORTED);
            CHECK(OpmQueryInterfaceAnswer(OpmWdkGuids[i].Bytes, opm, 0xFFFFu, v, &iface, V1_SIZE, V1_VERSION) ==
                  OPM_STATUS_NOT_SUPPORTED);
        }
    }
    // A GUID one byte away from the OPM GUID, at each of the 16 bytes.
    for (b = 0; b < 16u; ++b) {
        memcpy(near, opm, 16);
        near[b] ^= 0x01u;
        CHECK(OpmQueryInterfaceAnswer(near, opm, V1_SIZE, V1_VERSION, &iface, V1_SIZE, V1_VERSION) ==
              OPM_STATUS_NOT_SUPPORTED);
    }
}

static void handles(void)
{
    OPM_OUTPUTS t;
    unsigned long long h1 = SENTINEL, h2 = SENTINEL, h = SENTINEL, all[OPM_OUTPUT_SLOTS];
    unsigned i, s1;

    memset(&t, 0, sizeof(t));
    // Create on the output, with OPM and with COPP semantics: two live handles, neither 0.
    CHECK(OpmCreate(&t, TARGET, TARGET, OPM_SEMANTICS_OPM, &h1) == OPM_STATUS_SUCCESS);
    CHECK(OpmCreate(&t, TARGET, TARGET, OPM_SEMANTICS_COPP, &h2) == OPM_STATUS_SUCCESS);
    CHECK(h1 != SENTINEL && h1 != 0 && h2 != SENTINEL && h2 != 0 && h1 != h2);
    CHECK(OpmSlotOf(&t, h1) != OPM_OUTPUT_SLOTS && OpmSlotOf(&t, h2) != OPM_OUTPUT_SLOTS);
    CHECK(t.Created == 2u);
    s1 = OpmSlotOf(&t, h1);
    // Another target, or other semantics: refused, and the handle is unchanged.
    CHECK(OpmCreate(&t, TARGET + 1u, TARGET, OPM_SEMANTICS_OPM, &h) == OPM_STATUS_INVALID_TARGET && h == SENTINEL);
    CHECK(OpmCreate(&t, 0u, TARGET, OPM_SEMANTICS_OPM, &h) == OPM_STATUS_INVALID_TARGET && h == SENTINEL);
    CHECK(OpmCreate(&t, TARGET, TARGET, 2u, &h) == OPM_STATUS_OPM_NOT_SUPPORTED && h == SENTINEL);
    CHECK(OpmCreate(&t, TARGET, TARGET, 0xFFFFFFFFu, &h) == OPM_STATUS_OPM_NOT_SUPPORTED && h == SENTINEL);
    CHECK(t.Created == 2u);

    // Destroy, then destroy again: the second is an invalid handle and changes nothing.
    CHECK(OpmDestroy(&t, h1) == OPM_STATUS_SUCCESS);
    CHECK(t.Destroyed == 1u);
    CHECK(OpmDestroy(&t, h1) == OPM_STATUS_OPM_INVALID_HANDLE);
    CHECK(t.Destroyed == 1u && t.BadHandle == 1u);
    CHECK(OpmSlotOf(&t, h2) != OPM_OUTPUT_SLOTS);
    // Handles that the table never gave.
    CHECK(OpmDestroy(&t, 0ull) == OPM_STATUS_OPM_INVALID_HANDLE);
    CHECK(OpmDestroy(&t, SENTINEL) == OPM_STATUS_OPM_INVALID_HANDLE);
    CHECK(OpmDestroy(&t, h2 | (1ull << 40)) == OPM_STATUS_OPM_INVALID_HANDLE);
    CHECK(OpmDestroy(&t, (unsigned long long)OPM_OUTPUT_SLOTS + 1u) == OPM_STATUS_OPM_INVALID_HANDLE);
    CHECK(OpmDestroy(&t, 0xFFull) == OPM_STATUS_OPM_INVALID_HANDLE);
    CHECK(t.Destroyed == 1u && t.BadHandle == 6u);

    // The freed slot comes back with a new handle; the old handle stays invalid.
    CHECK(OpmCreate(&t, TARGET, TARGET, OPM_SEMANTICS_OPM, &h) == OPM_STATUS_SUCCESS);
    CHECK(OpmSlotOf(&t, h) == s1 && h != h1);
    CHECK(OpmSlotOf(&t, h1) == OPM_OUTPUT_SLOTS);
    CHECK(OpmDestroy(&t, h1) == OPM_STATUS_OPM_INVALID_HANDLE);
    CHECK(OpmDestroy(&t, h) == OPM_STATUS_SUCCESS);
    CHECK(OpmDestroy(&t, h2) == OPM_STATUS_SUCCESS);
    CHECK(OpmDestroy(&t, h2) == OPM_STATUS_OPM_INVALID_HANDLE);

    // A full table: the next create is STATUS_NO_MEMORY with the handle unchanged; one destroy frees a slot.
    for (i = 0; i < OPM_OUTPUT_SLOTS; ++i) CHECK(OpmCreate(&t, TARGET, TARGET, OPM_SEMANTICS_OPM, &all[i]) == OPM_STATUS_SUCCESS);
    for (i = 1; i < OPM_OUTPUT_SLOTS; ++i) CHECK(all[i] != all[i - 1u]);
    h = SENTINEL;
    CHECK(OpmCreate(&t, TARGET, TARGET, OPM_SEMANTICS_OPM, &h) == OPM_STATUS_NO_MEMORY && h == SENTINEL);
    CHECK(t.Full == 1u);
    CHECK(OpmDestroy(&t, all[5]) == OPM_STATUS_SUCCESS);
    CHECK(OpmCreate(&t, TARGET, TARGET, OPM_SEMANTICS_OPM, &h) == OPM_STATUS_SUCCESS && h != all[5]);
    CHECK(OpmDestroy(&t, all[5]) == OPM_STATUS_OPM_INVALID_HANDLE);
    for (i = 0; i < OPM_OUTPUT_SLOTS; ++i) if (i != 5u) CHECK(OpmDestroy(&t, all[i]) == OPM_STATUS_SUCCESS);
    CHECK(OpmDestroy(&t, h) == OPM_STATUS_SUCCESS);
    for (i = 0; i < OPM_OUTPUT_SLOTS; ++i) CHECK(t.Live[i] == 0);
}

// The seven refused calls: STATUS_GRAPHICS_OPM_NOT_SUPPORTED each time, with a live handle, a destroyed one or none,
// and the table is unchanged except for the count of refusals.
static void refused(void)
{
    OPM_OUTPUTS t, before;
    unsigned long long h = SENTINEL;
    unsigned call;

    memset(&t, 0, sizeof(t));
    CHECK(OpmCreate(&t, TARGET, TARGET, OPM_SEMANTICS_OPM, &h) == OPM_STATUS_SUCCESS);
    for (call = 0; call < 7u; ++call) {
        before = t;
        CHECK(OpmRefuse(&t) == OPM_STATUS_OPM_NOT_SUPPORTED);
        CHECK(t.Refused == before.Refused + 1u);
        before.Refused = t.Refused;
        CHECK(memcmp(&before, &t, sizeof(t)) == 0);
    }
    CHECK(OpmDestroy(&t, h) == OPM_STATUS_SUCCESS);
    CHECK(OpmRefuse(&t) == OPM_STATUS_OPM_NOT_SUPPORTED);
    CHECK(t.Refused == 8u);
    CHECK(OPM_STATUS_OPM_NOT_SUPPORTED != OPM_STATUS_SUCCESS && OPM_STATUS_OPM_NOT_SUPPORTED < 0);
}

static void query_log(void)
{
    QI_LOG log;
    const unsigned char* opm = guid_named("GUID_DEVINTERFACE_OPM");
    unsigned i;

    if (!opm) return;
    memset(&log, 0, sizeof(log));
    // The first request of a kind is logged, the same request again is not.
    CHECK(QiLogNote(&log, opm, V1_SIZE, 1u, OPM_STATUS_SUCCESS) == QI_LOG_LINE);
    CHECK(QiLogNote(&log, opm, V1_SIZE, 1u, OPM_STATUS_SUCCESS) == QI_LOG_NONE);
    // Another version, size, answer or GUID is another kind.
    CHECK(QiLogNote(&log, opm, V1_SIZE, 2u, OPM_STATUS_NOT_SUPPORTED) == QI_LOG_LINE);
    CHECK(QiLogNote(&log, opm, V1_SIZE + 8u, 1u, OPM_STATUS_SUCCESS) == QI_LOG_LINE);
    CHECK(QiLogNote(&log, opm, V1_SIZE, 1u, OPM_STATUS_NOT_SUPPORTED) == QI_LOG_LINE);
    CHECK(QiLogNote(&log, 0, 0u, 0u, OPM_STATUS_NOT_SUPPORTED) == QI_LOG_LINE);
    CHECK(QiLogNote(&log, 0, 0u, 0u, OPM_STATUS_NOT_SUPPORTED) == QI_LOG_NONE);
    CHECK(log.Count == 5u && log.Requests == 7u);
    // Fill the kinds with the other WDK GUIDs; one overflow line, then nothing.
    for (i = 0; i < OPM_WDK_GUID_COUNT && log.Count < QI_LOG_KINDS; ++i) {
        if (OpmWdkGuids[i].Bytes == opm) continue;
        CHECK(QiLogNote(&log, OpmWdkGuids[i].Bytes, 64u, 1u, OPM_STATUS_NOT_SUPPORTED) == QI_LOG_LINE);
    }
    CHECK(log.Count == QI_LOG_KINDS);
    CHECK(QiLogNote(&log, opm, 1u, 9u, OPM_STATUS_NOT_SUPPORTED) == QI_LOG_OVERFLOW);
    CHECK(QiLogNote(&log, opm, 2u, 9u, OPM_STATUS_NOT_SUPPORTED) == QI_LOG_NONE);
    CHECK(QiLogNote(&log, opm, V1_SIZE, 1u, OPM_STATUS_SUCCESS) == QI_LOG_NONE);
    for (i = 0; i < 1000u; ++i) CHECK(QiLogNote(&log, opm, 3u + i, 9u, OPM_STATUS_NOT_SUPPORTED) == QI_LOG_NONE);
    CHECK(log.Count == QI_LOG_KINDS && log.Overflow == 1u);
}

int main(void)
{
    query_interface();
    handles();
    refused();
    query_log();
    printf("opm_policy_test: %u checks, %u failures\n", checks, bad);
    return bad ? 1 : 0;
}
